const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');

// Uses an isolated browser. The form snapshot is generated by the focused
// component check; no draft or account is created on the production server.
async function main() {
  const base = process.env.CHECK_BASE_URL || 'http://127.0.0.1:18128';
  const apiBase = process.env.CHECK_API_URL || 'http://127.0.0.1:18129';
  const output = process.env.CHECK_OUTPUT || '/private/tmp/avbyartur-listing-release-20261028/browser';
  fs.mkdirSync(output, { recursive: true });
  const browser = await chromium.launch({
    headless: true,
    ...(process.env.CHECK_RESOLVE_HOST ? { args: [`--host-resolver-rules=MAP ${process.env.CHECK_RESOLVE_HOST} 127.0.0.1`] } : {})
  });
  try {
    const context = await browser.newContext({
      viewport: { width: 1440, height: 1000 },
      ignoreHTTPSErrors: process.env.CHECK_IGNORE_TLS === 'true'
    });
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', (error) => errors.push(error.message));
    const response = await page.goto(`${base}/login?next=%2Fsell`, { waitUntil: 'domcontentloaded' });
    assert.equal(response.status(), 200);
    await page.getByRole('button', { name: 'Создать аккаунт', exact: true }).click();
    for (const name of ['display_name', 'email', 'password', 'password_confirm', 'accept_terms', 'accept_privacy']) {
      await page.locator(`[name="${name}"]`).waitFor({ state: 'visible' });
    }
    await page.getByRole('button', { name: 'Зарегистрироваться', exact: true }).waitFor({ state: 'visible' });
    console.log('PASS: registration form');
    await page.screenshot({ path: path.join(output, 'registration.png'), fullPage: true });
    const styles = await page.locator('link[rel="stylesheet"]').evaluateAll((links) => links.map((link) => link.href));

    const requestOptions = process.env.CHECK_HEADERS_HOST ? { headers: { Host: process.env.CHECK_HEADERS_HOST } } : {};
    const api = await context.request.get(`${apiBase}/api/v1/listings?limit=1`, requestOptions);
    assert.equal(api.status(), 200);
    const { items } = await api.json();
    assert.ok(items.length > 0, 'A real public listing is required');
    const listing = items[0];
    assert.equal(typeof listing.view_count, 'number');
    assert.equal(typeof listing.has_phone, 'boolean');
    const detail = await context.request.get(`${apiBase}/api/v1/listings/${listing.id}`, requestOptions);
    assert.equal(detail.status(), 200);
    const payload = (await detail.json()).listing;
    assert.ok(payload.view_count >= listing.view_count);
    const href = `/cars/${encodeURIComponent(listing.make?.slug || listing.slug)}/${encodeURIComponent(listing.model?.slug || listing.slug)}/${listing.id}`;
    await page.goto(base + href, { waitUntil: 'domcontentloaded' });
    await page.locator('.detail-conversion-values').waitFor({ state: 'visible' });
    const converted = await page.locator('.detail-conversion-values').innerText();
    assert.match(converted, /USD/);
    assert.match(converted, /EUR/);
    await page.locator('.listing-views').first().waitFor({ state: 'visible' });
    await page.screenshot({ path: path.join(output, 'listing-desktop.png'), fullPage: true });
    for (const width of [320, 375, 390, 430]) {
      await page.setViewportSize({ width, height: 844 });
      assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), `Detail overflow at ${width}px`);
    }
    await page.screenshot({ path: path.join(output, 'listing-mobile.png'), fullPage: true });
    // React 418 also reproduces on the unchanged baseline. Keep it visible
    // in the result and reject every other browser error.
    const knownHydrationWarnings = errors.filter((error) => error.startsWith('Minified React error #418;'));
    assert.deepEqual(errors.filter((error) => !knownHydrationWarnings.includes(error)), [], 'Unexpected browser errors');
    if (knownHydrationWarnings.length) console.log(`Baseline hydration warning observed: ${knownHydrationWarnings.length}`);

    if (process.env.CHECK_FORM_SNAPSHOT) {
      const html = fs.readFileSync(process.env.CHECK_FORM_SNAPSHOT, 'utf8');
      const form = await context.newPage();
      await form.setContent(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">${styles.map((href) => `<link rel="stylesheet" href="${href}">`).join('')}</head><body><main class="page-width">${html}</main></body></html>`, { waitUntil: 'networkidle' });
      for (const width of [320, 375, 390, 430]) {
        await form.setViewportSize({ width, height: 844 });
        const dimensions = await form.evaluate(() => ({
          width: innerWidth, content: document.documentElement.scrollWidth,
          sizes: [...document.querySelectorAll('.field input, .field select')].map((input) => parseFloat(getComputedStyle(input).fontSize))
        }));
        assert.ok(dimensions.content <= dimensions.width + 1, `Contact form overflow at ${width}px`);
        assert.ok(dimensions.sizes.every((size) => size >= 16), 'iOS focus zoom prevention requires at least 16px controls');
      }
      await form.screenshot({ path: path.join(output, 'contact-form-mobile.png'), fullPage: true });
    }
    console.log('PASS: registration, public API contract, USD/EUR, view counter, mobile widths' + (process.env.CHECK_FORM_SNAPSHOT ? ', contact form sizing' : ''));
    await context.close();
  } finally {
    await browser.close();
  }
}

main().catch((error) => { console.error(error.message); process.exit(1); });
